//! Golden-file tests defending the byte-for-byte determinism invariant.
//!
//! The crate promises that `compress(x)` produces identical output for the same
//! input across machines, processes, and compatible crate versions. The encoder
//! in `zstd-safe` is not guaranteed by upstream to be byte-stable across versions,
//! so this module pins down a corpus of inputs and asserts that the exact
//! compressed bytes match a fixed expected sequence. Any future change that
//! alters output — intended or not — fails this test.
//!
//! To regenerate the golden values after an intentional encoder-affecting change
//! (e.g., a level bump or a `zstd-safe` version bump), run:
//!
//! ```text
//! cargo test --release print_golden_hex -- --ignored --nocapture
//! ```
//!
//! and paste the printed hex strings into the corresponding entries of `corpus()`.

#![allow(clippy::expect_used)]

use crate::{compress, compress_into, decompress};

fn lcg_bytes(len: usize) -> Vec<u8> {
    let mut x: u64 = 0x1234_5678_9ABC_DEF0;
    let mut out = Vec::with_capacity(len);
    for _ in 0..len {
        x = x.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
        out.push(x.to_le_bytes()[4]);
    }
    out
}

fn ascending_4096() -> Vec<u8> {
    (0u16..4096)
        .map(|i| u8::try_from(i % 251).expect("modulo 251 fits in u8"))
        .collect()
}

fn lcg_mixed_4096() -> Vec<u8> {
    let mut out = vec![0u8; 4096];
    out[2048..].copy_from_slice(&lcg_bytes(2048));
    out
}

fn json_repeated_4096() -> Vec<u8> {
    let base = b"{\"id\":123,\"name\":\"example\",\"active\":true,\"roles\":[\"a\",\"b\"]}\n";
    let mut out = Vec::with_capacity(4096);
    while out.len() < 4096 {
        let rem = 4096 - out.len();
        if rem >= base.len() {
            out.extend_from_slice(base);
        } else {
            out.extend_from_slice(&base[..rem]);
        }
    }
    out
}

fn to_hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(char::from_digit(u32::from(b >> 4), 16).expect("nibble"));
        s.push(char::from_digit(u32::from(b & 0x0F), 16).expect("nibble"));
    }
    s
}

fn from_hex(s: &str) -> Vec<u8> {
    assert!(
        s.len().is_multiple_of(2),
        "hex string must have even length"
    );
    let mut out = Vec::with_capacity(s.len() / 2);
    let bytes = s.as_bytes();
    for chunk in bytes.chunks(2) {
        let hi = nibble(chunk[0]);
        let lo = nibble(chunk[1]);
        out.push((hi << 4) | lo);
    }
    out
}

fn nibble(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        b'A'..=b'F' => c - b'A' + 10,
        _ => panic!("invalid hex character: {c:?}"),
    }
}

fn corpus() -> Vec<(&'static str, Vec<u8>, &'static str)> {
    vec![
        ("empty",              Vec::new(),                                     "28b52ffd2000010000"),
        ("single_byte",        vec![0x42],                                     "28b52ffd200109000042"),
        ("zeros_64",           vec![0u8; 64],                                  "28b52ffd20403d000008000100447242"),
        ("zeros_4096",         vec![0u8; 4096],                                "28b52ffd60000f45000008000100fcc77742"),
        ("counter_256",        (u8::MIN..=u8::MAX).collect(),                  ""),
        ("ascending_4096",     ascending_4096(),                               ""),
        ("lcg_31",             lcg_bytes(31),                                  "28b52ffd201ff9000043c31430faa77cac2860595d4cf025692d651236ecafcef2cce91cd86ecf7d"),
        ("lcg_512",            lcg_bytes(512),                                 ""),
        ("lcg_2048",           lcg_bytes(2048),                                ""),
        ("lcg_4096",           lcg_bytes(4096),                                ""),
        ("lcg_mixed_4096",     lcg_mixed_4096(),                               ""),
        ("text_short",         b"deterministic payload deterministic payload".to_vec(), "28b52ffd202be50000b064657465726d696e6973746963207061796c6f6164200100f29b4d"),
        ("json_repeated_4096", json_repeated_4096(),                           "28b52ffd60000f2d0200c4037b226964223a3132332c226e616d65223a226578616d706c65222c22616374697665223a747275652c22726f6c6573223a5b2261222c2262225d7d0a01001cfcef2b28"),
    ]
}

#[test]
fn compressed_output_matches_golden_bytes() {
    for (name, input, expected_hex) in corpus() {
        if expected_hex.is_empty() {
            continue;
        }
        let compressed = compress(&input).expect("compression should succeed");
        let expected = from_hex(expected_hex);
        assert_eq!(
            compressed.as_slice(),
            expected.as_slice(),
            "golden mismatch for {name}: got {} bytes, expected {} bytes",
            compressed.len(),
            expected.len(),
        );
    }
}

#[test]
fn compressed_output_is_reproducible_within_process() {
    for (name, input, _) in corpus() {
        let baseline = compress(&input).expect("compression should succeed");
        for iteration in 0..64 {
            let next = compress(&input).expect("compression should succeed");
            assert_eq!(
                next.as_slice(),
                baseline.as_slice(),
                "non-deterministic output for {name} on iteration {iteration}",
            );
        }
    }
}

#[test]
fn compress_into_matches_compress() {
    for (name, input, _) in corpus() {
        let via_alloc = compress(&input).expect("compress should succeed");

        let mut buffer = vec![0u8; via_alloc.len().saturating_add(1024)];
        let written = compress_into(&input, &mut buffer).expect("compress_into should succeed");

        assert_eq!(
            written,
            via_alloc.len(),
            "compress_into wrote a different number of bytes for {name}",
        );
        assert_eq!(
            &buffer[..written],
            via_alloc.as_slice(),
            "compress_into produced different bytes than compress for {name}",
        );
    }
}

#[test]
fn golden_bytes_decompress_to_input() {
    for (name, input, expected_hex) in corpus() {
        if expected_hex.is_empty() {
            continue;
        }
        let golden = from_hex(expected_hex);
        let decompressed = decompress(&golden).expect("decompression should succeed");
        assert_eq!(
            decompressed.as_slice(),
            input.as_slice(),
            "decoding the golden bytes did not reproduce the input for {name}",
        );
    }
}

#[test]
fn round_trip_matches_input() {
    for (name, input, _) in corpus() {
        let compressed = compress(&input).expect("compression should succeed");
        let decompressed = decompress(&compressed).expect("decompression should succeed");
        assert_eq!(
            decompressed.as_slice(),
            input.as_slice(),
            "round-trip mismatch for {name}",
        );
    }
}

#[test]
#[ignore = "regenerates golden hex constants; run manually with --nocapture"]
fn print_golden_hex() {
    for (name, input, _) in corpus() {
        let compressed = compress(&input).expect("compression should succeed");
        println!("{name}\t{}", to_hex(&compressed));
    }
}
